<template>
  <div>
    <div class="page-header"><h1 class="page-title">奖励金管理</h1><p class="page-desc">创建平台奖励金，发放给老板和零工，支持立即/定时、固定/随机金额</p></div>
    <div class="stat-cards"><div v-for="s in statCards" :key="s.label" class="stat-card"><div class="stat-card-header"><span class="stat-card-title">{{ s.label }}</span><div :class="['stat-card-icon', s.color]"><i :class="['fas', s.icon]"></i></div></div><div class="stat-card-value">{{ s.money ? `¥${money(s.value)}` : number(s.value) }}<span v-if="s.unit" class="stat-unit"> {{ s.unit }}</span></div><div class="stat-card-change" :class="s.up ? 'up' : ''"><i v-if="s.rate" class="fas fa-arrow-up"></i><span>{{ s.note }}</span></div></div></div>
    <div class="card"><div class="tabs-bar"><div v-for="t in tabs" :key="t" :class="['tab-btn', { active: activeTab === t }]" @click="activeTab = t">{{ t }}<span class="tab-count">{{ tabCount(t) }}</span></div><div class="tab-spacer"></div><button class="btn btn-primary btn-sm" @click="openDrawer"><i class="fas fa-plus"></i> 创建奖励金</button></div>
      <el-table :data="filteredRewards" stripe :header-cell-style="{ background: '#F9FAFB', color: '#6B7280', fontWeight: 500 }"><el-table-column prop="rewardNo" label="奖励单号" min-width="150"><template #default="{ row }"><span class="rw-no">{{ row.rewardNo }}</span></template></el-table-column><el-table-column prop="name" label="奖励名称" min-width="155"><template #default="{ row }"><span class="rw-name">{{ row.name }}</span></template></el-table-column><el-table-column label="发放对象" width="100"><template #default="{ row }"><span :class="['target-badge', targetClass(row.target)]"><i :class="['fas', targetIcon(row.target)]"></i>{{ row.target }}</span></template></el-table-column><el-table-column label="发放范围" width="120"><template #default="{ row }"><span class="scope-tag">{{ row.scope === '全部' ? '全体发放' : `指定 ${row.count} 人名单` }}</span></template></el-table-column><el-table-column label="发放人数" width="95"><template #default="{ row }">{{ number(row.count) }} 人</template></el-table-column><el-table-column label="单人金额" width="120"><template #default="{ row }"><span class="money">{{ amountText(row) }}</span></template></el-table-column><el-table-column label="发放总额" width="120"><template #default="{ row }"><span class="money total">¥{{ money(row.total) }}</span></template></el-table-column><el-table-column label="状态" width="90"><template #default="{ row }"><span :class="['status-badge', statusClass(row.status)]">{{ row.status }}</span></template></el-table-column><el-table-column label="发放时间" width="160"><template #default="{ row }"><span class="time-cell">{{ formatTime(row.sendAt) }}</span></template></el-table-column><el-table-column label="创建时间" width="160"><template #default="{ row }"><span class="time-cell">{{ formatTime(row.createdAt) }}</span></template></el-table-column><el-table-column label="操作" min-width="135" fixed="right"><template #default="{ row }"><el-button link type="primary" size="small" @click="showDetail(row)">详情</el-button><el-button v-if="row.status === '待发放'" link type="danger" size="small" @click="cancel(row)">撤销</el-button></template></el-table-column></el-table>
      <div class="pagination"><div class="pagination-info">共 {{ total }} 条记录</div><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[10,20,50,100]" :total="total" layout="sizes, prev, pager, next, jumper" background @size-change="load" @current-change="load" /></div>
    </div>
    <el-drawer v-model="drawerVisible" title="创建奖励金" size="620px" destroy-on-close><el-form label-position="top"><div class="form-section">基础信息</div><el-form-item label="奖励名称" required><el-input v-model="form.name" maxlength="20" placeholder="如：中秋开工激励金" /></el-form-item><el-form-item label="发放对象" required><el-radio-group v-model="form.target"><el-radio-button label="老板">老板</el-radio-button><el-radio-button label="零工">零工</el-radio-button><el-radio-button label="全部用户">全部用户</el-radio-button></el-radio-group></el-form-item><el-form-item label="发放范围" required><el-radio-group v-model="form.scope" :disabled="form.target === '全部用户'"><el-radio label="全部">全体发放</el-radio><el-radio label="指定">指定用户</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.scope === '指定' && form.target !== '全部用户'" label="用户名单" required><div class="recipient-picker"><el-input v-model="recipientKeyword" clearable placeholder="搜索姓名、昵称或手机号" prefix-icon="Search" /><div v-loading="recipientLoading" class="recipient-list"><label v-for="user in recipientList" :key="user.id" class="recipient-item"><el-checkbox :model-value="selectedRecipients.has(user.id)" @change="toggleRecipient(user, $event)" /><div class="recipient-main"><div class="recipient-name">{{ recipientName(user) }} <span class="recipient-role">{{ user.role || form.target }}</span></div><div class="recipient-sub">{{ user.phone || '-' }}<template v-if="user.companyName"> · {{ user.companyName }}</template></div></div><span :class="['recipient-status', user.status === '正常' ? 'normal' : '']">{{ user.status || '-' }}</span></label><el-empty v-if="!recipientLoading && !recipientList.length" description="暂无候选用户" :image-size="54" /></div><div class="recipient-footer"><span>已选择 {{ users.length }} 人</span><el-pagination v-model:current-page="recipientPage" :page-size="recipientSize" :total="recipientTotal" small layout="prev, pager, next" @current-change="loadRecipients" /></div></div></el-form-item><div class="form-section mt">金额设置</div><el-form-item label="金额方式" required><el-radio-group v-model="form.amountMode"><el-radio label="fixed">固定金额（每人相同）</el-radio><el-radio label="random">随机金额（区间内随机）</el-radio></el-radio-group></el-form-item><div v-if="form.amountMode === 'fixed'" class="inline-inputs"><span>每人</span><el-input-number v-model="form.amount" :min="0.01" :precision="2" controls-position="right" /><span>元</span></div><div v-else class="inline-inputs"><span>每人随机</span><el-input-number v-model="form.min" :min="0.01" :precision="2" controls-position="right" /><span>元至</span><el-input-number v-model="form.max" :min="0.01" :precision="2" controls-position="right" /><span>元</span></div><el-form-item v-if="form.scope === '全部'" label="发放人数" required style="margin-top:16px"><el-input-number v-model="form.count" :min="1" controls-position="right" /><span class="inline-unit"> 人</span></el-form-item><div class="total-preview"><span><i class="fas fa-calculator"></i> 预计发放总额</span><b>¥{{ money(estimatedTotal) }} <small>人均约 ¥{{ money(averageAmount) }}</small></b></div><div class="form-section mt">发放设置</div><el-form-item label="发放时间" required><el-radio-group v-model="form.sendMode"><el-radio label="now">立即发放</el-radio><el-radio label="timing">定时发放</el-radio></el-radio-group><el-date-picker v-if="form.sendMode === 'timing'" v-model="form.sendAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" placeholder="选择发放时间" style="width:100%;margin-top:10px" /></el-form-item><el-form-item label="奖励说明"><el-input v-model="form.remark" type="textarea" :rows="3" placeholder="将展示在用户奖励金账单中，如：平台中秋活动奖励" /></el-form-item></el-form><template #footer><el-button @click="drawerVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">确认创建</el-button></template></el-drawer>
    <el-dialog v-model="detailVisible" title="奖励金详情" width="600px"><el-descriptions v-if="current" :column="2" border><el-descriptions-item label="奖励单号">{{ current.rewardNo }}</el-descriptions-item><el-descriptions-item label="状态"><span :class="['status-badge', statusClass(current.status)]">{{ current.status }}</span></el-descriptions-item><el-descriptions-item label="奖励名称">{{ current.name }}</el-descriptions-item><el-descriptions-item label="发放对象">{{ current.target }}</el-descriptions-item><el-descriptions-item label="发放范围">{{ current.scope === '全部' ? '全体发放' : '指定用户' }}</el-descriptions-item><el-descriptions-item label="发放时间">{{ formatTime(current.sendAt) }}</el-descriptions-item><el-descriptions-item label="发放人数">{{ number(current.count) }} 人</el-descriptions-item><el-descriptions-item label="单人金额">{{ amountText(current) }}</el-descriptions-item><el-descriptions-item label="发放总额"><span class="money total">¥{{ money(current.total) }}</span></el-descriptions-item><el-descriptions-item label="创建时间">{{ formatTime(current.createdAt) }}</el-descriptions-item><el-descriptions-item label="奖励说明" :span="2">{{ current.remark || '-' }}</el-descriptions-item></el-descriptions><template #footer><el-button @click="detailVisible = false">关闭</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { cancelReward, createReward, getRewardStats, listRewardRecipients, listRewards } from '@/api/reward'
const tabs = ['全部', '待发放', '已发放', '已撤销']; const activeTab = ref('全部'); const rewards = ref([]); const total = ref(0); const page = ref(1); const size = ref(10); const drawerVisible = ref(false); const detailVisible = ref(false); const current = ref(null); const saving = ref(false); const stats = reactive({ totalAmount: 0, monthAmount: 0, pendingCount: 0, distributedCount: 0, canceledCount: 0, totalCount: 0, coverage: 0, bossCoverage: 0, workerCoverage: 0, totalRate: 0, monthCoverage: 0 }); const form = reactive({ name: '', target: '老板', scope: '全部', amountMode: 'fixed', amount: 20, min: 5, max: 50, count: 1000, sendMode: 'now', sendAt: '', remark: '' })
const recipientKeyword = ref(''); const recipientPage = ref(1); const recipientSize = 20; const recipientTotal = ref(0); const recipientList = ref([]); const recipientLoading = ref(false); const selectedRecipients = reactive(new Map())
const users = computed(() => Array.from(selectedRecipients.keys())); const number = v => Number(v || 0).toLocaleString('zh-CN'); const money = v => Number(v || 0).toFixed(2); const formatTime = v => v ? String(v).replace('T', ' ').slice(0, 19) : '-'; const amountText = r => r.amountMode === 'fixed' ? `¥${money(r.amount)}` : `¥${money(r.min)}~${money(r.max)}`; const targetClass = t => t === '零工' ? 't-worker' : 't-boss'; const targetIcon = t => t === '零工' ? 'fa-hard-hat' : t === '老板' ? 'fa-user-tie' : 'fa-users'; const statusClass = s => ({ 待发放: 'warning', 已发放: 'success', 已撤销: 'default' }[s] || 'default'); const filteredRewards = computed(() => rewards.value); const tabCount = t => ({ 全部: stats.totalCount, 待发放: stats.pendingCount, 已发放: stats.distributedCount, 已撤销: stats.canceledCount }[t] ?? 0); const estimatedCount = computed(() => form.scope === '指定' ? users.value.length : Number(form.count || 0)); const averageAmount = computed(() => form.amountMode === 'fixed' ? Number(form.amount || 0) : (Number(form.min || 0) + Number(form.max || 0)) / 2); const estimatedTotal = computed(() => averageAmount.value * estimatedCount.value); const statCards = computed(() => [{ label: '累计发放金额', value: stats.totalAmount, money: true, icon: 'fa-sack-dollar', note: `较上季度 +${stats.totalRate || 0}%`, rate: true, up: true }, { label: '本月发放', value: stats.monthAmount, money: true, color: 'green', icon: 'fa-gift', note: `覆盖 ${number(stats.monthCoverage)} 人次` }, { label: '待发放活动', value: stats.pendingCount, color: 'yellow', icon: 'fa-clock', note: '等待定时执行' }, { label: '累计覆盖人次', value: stats.coverage, color: 'blue', icon: 'fa-users', unit: '', note: `老板 ${number(stats.bossCoverage)} · 零工 ${number(stats.workerCoverage)}`, rate: true, up: true }])
const normalize = r => ({ ...r, rewardNo: r.rewardNo || r.no, count: r.count ?? r.peopleCount ?? 0, total: r.total ?? r.totalAmount ?? 0 }); async function load () { try { const [r, sr] = await Promise.all([listRewards({ status: activeTab.value === '全部' ? undefined : activeTab.value, page: page.value - 1, size: size.value }), getRewardStats()]); const d = r.data; const list = Array.isArray(d) ? d : (d?.content || d?.list || []); rewards.value = list.map(normalize); total.value = r.total ?? d?.totalElements ?? d?.total ?? list.length; Object.assign(stats, sr.data || {}) } catch { rewards.value = []; total.value = 0; ElMessage.error('加载奖励金失败') } }
function showDetail (row) { current.value = row; detailVisible.value = true }
function openDrawer () { selectedRecipients.clear(); recipientKeyword.value = ''; recipientPage.value = 1; Object.assign(form, { name: '', target: '老板', scope: '全部', amountMode: 'fixed', amount: 20, min: 5, max: 50, count: 1000, sendMode: 'now', sendAt: '', remark: '' }); drawerVisible.value = true }
function recipientName (user) { return user.nickname || user.realName || user.username || `用户${user.id}` }
function toggleRecipient (user, checked) { if (checked) selectedRecipients.set(user.id, user); else selectedRecipients.delete(user.id) }
function apiError (error, fallback) { const status = error?.response?.status; const message = error?.response?.data?.message || error?.message; if (status === 403) ElMessage.error('仅管理员可操作'); else if (status === 400 && message) ElMessage.error(message); else ElMessage.error(message || fallback) }
async function loadRecipients () { if (form.target === '全部用户' || form.scope !== '指定') { recipientList.value = []; recipientTotal.value = 0; return }; recipientLoading.value = true; try { const res = await listRewardRecipients({ target: form.target, keyword: recipientKeyword.value || undefined, page: recipientPage.value - 1, size: recipientSize }); const data = res.data; recipientList.value = Array.isArray(data) ? data : (data?.content || data?.list || []); recipientTotal.value = res.total ?? data?.totalElements ?? data?.total ?? 0 } catch (error) { recipientList.value = []; recipientTotal.value = 0; apiError(error, '加载候选用户失败') } finally { recipientLoading.value = false } }
async function save () { if (!form.name) return ElMessage.warning('请输入奖励名称'); if (form.scope === '指定' && !users.value.length) return ElMessage.warning('请选择指定用户'); if (form.scope === '全部' && estimatedCount.value < 1) return ElMessage.warning('请填写发放人数'); if (form.amountMode === 'fixed' && !(form.amount > 0)) return ElMessage.warning('请填写每人奖励金额'); if (form.amountMode === 'random' && (!(form.min > 0) || !(form.max > form.min))) return ElMessage.warning('请填写正确的随机金额区间'); if (form.sendMode === 'timing' && !form.sendAt) return ElMessage.warning('请选择定时发放时间'); saving.value = true; try { const payload = { name: form.name, target: form.target, scope: form.scope, users: form.scope === '指定' ? users.value : [], amountMode: form.amountMode, amount: form.amount, min: form.min, max: form.max, count: estimatedCount.value, sendMode: form.sendMode, sendAt: form.sendAt, remark: form.remark }; await createReward(payload); ElMessage.success('奖励金创建成功'); drawerVisible.value = false; load() } catch (error) { apiError(error, '创建奖励金失败') } finally { saving.value = false } }
async function cancel (row) { try { await ElMessageBox.confirm('待发放活动撤销后将不再执行；已到账用户的奖励金不受影响。', '确认撤销奖励金', { type: 'warning', confirmButtonText: '确认撤销', cancelButtonText: '再想想' }); await cancelReward(row.id || row.rewardNo); ElMessage.success('已撤销'); load() } catch (e) { if (e !== 'cancel' && e !== 'close') apiError(e, '撤销失败') } }
watch(activeTab, () => { page.value = 1; load() }); watch(() => form.target, value => { if (value === '全部用户') form.scope = '全部'; selectedRecipients.clear(); recipientPage.value = 1; loadRecipients() }); watch(() => form.scope, () => { recipientPage.value = 1; loadRecipients() }); watch(recipientKeyword, () => { recipientPage.value = 1; loadRecipients() }); watch(drawerVisible, value => { if (value) loadRecipients() })
onMounted(load)
</script>
<style scoped>
.tabs-bar{display:flex;gap:4px;align-items:center;border-bottom:1px solid var(--border);margin-bottom:16px}.tab-btn{padding:10px 18px;font-size:14px;color:var(--text-secondary);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}.tab-btn.active{color:var(--primary);border-bottom-color:var(--primary);font-weight:600}.tab-count{display:inline-block;margin-left:5px;font-size:12px;background:var(--bg-page);border-radius:10px;padding:0 7px}.tab-spacer{flex:1}.rw-name{font-weight:600;font-size:13px;color:#111827}.rw-no{font-size:12px;color:var(--text-muted);font-family:monospace}.target-badge{display:inline-flex;align-items:center;gap:4px;font-size:12px;padding:3px 9px;border-radius:6px}.t-boss{background:#FFF7E6;color:#D97706}.t-worker{background:#F0FDF4;color:#16A34A}.scope-tag,.time-cell{font-size:12px;color:var(--text-secondary);white-space:nowrap}.money{font-weight:700;color:#EA580C}.money.total{color:#DC2626}.form-section{font-size:13px;font-weight:600;color:#374151;margin:4px 0 14px;padding-left:10px;border-left:3px solid #EA580C}.form-section.mt{margin-top:22px}.inline-inputs{display:flex;align-items:center;gap:8px}.inline-unit{font-size:13px;color:var(--text-muted)}.form-tip{font-size:12px;color:var(--text-muted);margin-top:6px}.total-preview{margin-top:14px;padding:14px 16px;border-radius:10px;background:linear-gradient(135deg,#FFF7ED,#FFEDD5);color:#9A3412;display:flex;align-items:center;justify-content:space-between}.total-preview b{font-size:20px}.total-preview small{font-size:12px;font-weight:400}.stat-unit{font-size:14px;color:var(--text-muted);font-weight:400}.recipient-picker{border:1px solid var(--border);border-radius:10px;padding:10px;background:#fff}.recipient-list{max-height:260px;overflow:auto;margin-top:10px;border-top:1px solid #F3F4F6}.recipient-item{display:flex;align-items:center;gap:8px;padding:10px 4px;border-bottom:1px solid #F3F4F6;cursor:pointer}.recipient-item:hover{background:#FFF7ED}.recipient-main{flex:1;min-width:0}.recipient-name{color:var(--text-primary);font-size:13px;font-weight:500}.recipient-role{margin-left:5px;padding:2px 6px;border-radius:4px;background:#F3F4F6;color:var(--text-muted);font-size:11px;font-weight:400}.recipient-sub{overflow:hidden;margin-top:3px;color:var(--text-muted);font-size:12px;text-overflow:ellipsis;white-space:nowrap}.recipient-status{color:var(--text-muted);font-size:12px}.recipient-status.normal{color:var(--success)}.recipient-footer{display:flex;align-items:center;justify-content:space-between;padding-top:8px;color:var(--text-muted);font-size:12px}
</style>
